package rpc

import (
	"context"
	"fmt"
	"math/big"

	"github.com/gateway-fm/chain-indexer/pkg/eth/common"
)

// balanceReaderCode is the runtime code of balancereader/BalanceReader.sol (solc 0.8.20, --optimize-runs 200).
// It is never deployed: BalancesOf injects it at balanceReaderAddr with an eth_call state override.
const balanceReaderCode = ""

var balanceReaderAddr = common.HexToAddress("0x00000000000000000000000000000000b41a4ce5")

// balances(address,address[])
var balancesSelector = common.FromHex("0xd3e5ca87")

// BalancesOf reads balanceOf(holder) of one token for every holder in a single eth_call at latest. ok[i] is false
// when that holder's balanceOf failed; its value must not be stored.
func (c *Client) BalancesOf(ctx context.Context, token common.Address, holders []common.Address, skipL1Charging bool) ([]*big.Int, []bool, error) {
	data := make([]byte, 0, 4+32*(3+len(holders)))
	data = append(data, balancesSelector...)
	data = append(data, common.LeftPadBytes(token.Bytes(), 32)...)
	data = append(data, common.LeftPadBytes(big.NewInt(64).Bytes(), 32)...)
	data = append(data, common.LeftPadBytes(big.NewInt(int64(len(holders))).Bytes(), 32)...)
	for _, h := range holders {
		data = append(data, common.LeftPadBytes(h.Bytes(), 32)...)
	}
	res, err := c.raw.CallWithCodeOverride(ctx, balanceReaderAddr, data, balanceReaderCode, skipL1Charging)
	if err != nil {
		return nil, nil, err
	}
	n := len(holders)
	word := func(off int) (*big.Int, error) {
		if off < 0 || off+32 > len(res) {
			return nil, fmt.Errorf("balance reader: short result (%d bytes)", len(res))
		}
		return new(big.Int).SetBytes(res[off : off+32]), nil
	}
	outOff, err := word(0)
	if err != nil {
		return nil, nil, err
	}
	okOff, err := word(32)
	if err != nil {
		return nil, nil, err
	}
	values := make([]*big.Int, n)
	ok := make([]bool, n)
	for i := 0; i < n; i++ {
		if values[i], err = word(int(outOff.Int64()) + 32 + 32*i); err != nil {
			return nil, nil, err
		}
		flag, err := word(int(okOff.Int64()) + 32 + 32*i)
		if err != nil {
			return nil, nil, err
		}
		ok[i] = flag.Sign() != 0
	}
	return values, ok, nil
}
